import six
from abc import ABCMeta
from functools import partial
from taf.ue.plugin.mtk.action_verifier import MessageVerifier, ManyTriesTrueFalseVerifier
from taf.ue.plugin.mtk.exceptions import (AttachFailure, DetachFailure, CreatePduSessionFailure,
                                          RebootNotReady, ManyTriesStillFail,
                                          CriteriaMessageMismatched, CriteriaMessageHappenedOutOfOrder)


@six.add_metaclass(ABCMeta)
class MaceVerifier(MessageVerifier):

    def __init__(self, mace_proxy=None):
        self._mace_proxy = mace_proxy


class OTAMessageAlwaysPassVerifier(MaceVerifier):
    def __init__(self, mace_proxy=None):
        super(OTAMessageAlwaysPassVerifier, self).__init__(mace_proxy=mace_proxy)

    def verify(self):
        self._mace_proxy.read_latest_ota_message()


class AttachVerifier(MaceVerifier):
    def __init__(self, mace_proxy=None):
        super(AttachVerifier, self).__init__(mace_proxy=mace_proxy)

    def verify(self):
        pass


class SAAttachUESideVerifier(AttachVerifier):

    def __init__(self, mace_proxy=None):
        super(SAAttachUESideVerifier, self).__init__(mace_proxy=mace_proxy)

    def verify(self):
        critical_string = "5GMM_REGISTRATION_COMPLETE"
        output = self._mace_proxy.read_ota_message_until(critical_string, wait_timeout=120)
        try:
            self.check_in_msg_string_list([critical_string], output)
        except (CriteriaMessageMismatched, CriteriaMessageHappenedOutOfOrder) as e:
            raise AttachFailure(e)


class NSAAttachUESideVerifier(AttachVerifier):

    def __init__(self, mace_proxy=None):
        super(NSAAttachUESideVerifier, self).__init__(mace_proxy=mace_proxy)

    def verify(self):

        attach_critical_string_nr = "SRB1_NR_RRCReconfiguration_Complete"
        output = self._mace_proxy.read_ota_message_until(attach_critical_string_nr, wait_timeout=120)

        pdu_critical_string = "MSG_ACTIVATE_DEFAULT_EPS_BEARER_CONTEXT_ACCEPT"
        try:
            self.check_in_msg_string_list([pdu_critical_string], output)
        except (CriteriaMessageMismatched, CriteriaMessageHappenedOutOfOrder) as e:
            raise AttachFailure(CreatePduSessionFailure(e))

        attach_critical_string_lte = "EMM_Attach_Complete"

        try:
            self.check_in_msg_string_list([attach_critical_string_lte, attach_critical_string_nr], output)
        except (CriteriaMessageMismatched, CriteriaMessageHappenedOutOfOrder) as e:
            raise AttachFailure(e)


class DetachVerifier(MaceVerifier):
    def __init__(self, mace_proxy=None):
        super(DetachVerifier, self).__init__(mace_proxy=mace_proxy)

    def _verify(self, detach_req, detach_res):
        output = self._mace_proxy.read_ota_message_until(detach_res, wait_timeout=120)

        try:
            self.check_in_msg_string_list([detach_req, detach_res], output)
        except (CriteriaMessageMismatched, CriteriaMessageHappenedOutOfOrder) as e:
            raise DetachFailure(e)

    def verify(self):
        pass


class SADetachUESideVerifier(DetachVerifier):

    def __init__(self, mace_proxy=None):
        super(SADetachUESideVerifier, self).__init__(mace_proxy=mace_proxy)

    def verify(self):
        detach_critical_string_req = "5GMM_DEREGISTRATION_REQUEST"
        detach_critical_string_res = "NR_RRCRelease"
        self._verify(detach_critical_string_req, detach_critical_string_res)


class NSADetachUESideVerifier(DetachVerifier):

    def __init__(self, mace_proxy=None):
        super(NSADetachUESideVerifier, self).__init__(mace_proxy=mace_proxy)

    def verify(self):
        detach_critical_string_req = "EMM_Detach_Request"
        detach_critical_string_res = "ERRC_RRCConnectionRelease"
        self._verify(detach_critical_string_req, detach_critical_string_res)


