class PDNUESideVerifier(MaceVerifier):

    def __init__(self, mace_proxy=None):
        super(PDNUESideVerifier, self).__init__(mace_proxy=mace_proxy)

    def _verify(self, critical_string):
        output = self._mace_proxy.read_ota_message_until(critical_string, wait_timeout=120)

        try:
            self.check_in_msg_string_list([critical_string], output)
        except (CriteriaMessageMismatched, CriteriaMessageHappenedOutOfOrder) as e:
            raise CreatePduSessionFailure(e)

    def verify(self):
        pass


class SAPDNUESideVerifier(PDNUESideVerifier):

    def __init__(self, mace_proxy=None):
        super(SAPDNUESideVerifier, self).__init__(mace_proxy=mace_proxy)

    def verify(self):
        critical_string = "VGSM_PDU_SESSION_ESTABLISHMENT_ACCEPT"
        self._verify(critical_string)


