class RebootVerifier(ManyTriesTrueFalseVerifier):
    def __init__(self, mace_proxy=None, one_wait_timeout=10, tries=3):
        super(RebootVerifier, self).__init__(mace_proxy.is_com_ports_ready, one_wait_timeout, tries)

    def verify(self):
        try:
            super(RebootVerifier, self).verify()
        except ManyTriesStillFail as e:
            raise RebootNotReady("reboot not ready {}".format(str(e)))


class PetrusRebootVerifier(ManyTriesTrueFalseVerifier):
    def __init__(self, mace_proxy=None, one_wait_timeout=10, tries=3):
        is_com_ports_ready = partial(mace_proxy.is_com_ports_ready,
                                     ['USB Serial Device', 'MediaTek USB VCOM (Android)'])
        super(PetrusRebootVerifier, self).__init__(is_com_ports_ready, one_wait_timeout, tries)

    def verify(self):
        try:
            super(PetrusRebootVerifier, self).verify()
        except ManyTriesStillFail as e:
            raise RebootNotReady("reboot not ready {}".format(str(e)))
